using Jellyfin.Plugin.PositionedSubtitles.Configuration;
using Jellyfin.Plugin.PositionedSubtitles.Services;

namespace Jellyfin.Plugin.PositionedSubtitles.Tests;

[TestClass]
public sealed class AssBuilderTests
{
    private const string YellowStyle = "Style: Default,Arial,64,&H0000FFFF,&H0000FFFF,&H00000000,&H80000000,0,0,0,0,100,100,0,0,1,3,1.5,2,80,80,55,1";

    /// <summary>Same shape as ffmpeg's SRT -> ASS output.</summary>
    private const string FfmpegAss =
        "[Script Info]\n; Script generated by FFmpeg\nScriptType: v4.00+\nPlayResX: 384\nPlayResY: 288\n\n" +
        "[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n" +
        "Style: Default,Arial,16,&Hffffff,&Hffffff,&H0,&H0,0,0,0,0,100,100,0,0,1,1,0,2,10,10,10,1\n\n" +
        "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n" +
        "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,{\\an8}Napis u góry.\n" +
        "Dialogue: 0,0:00:03.00,0:00:04.00,Default,,0,0,0,,Zwykły napis.\n";

    /// <summary>Same shape as a typical embedded WEB release ASS track: one white Default style.</summary>
    private const string ReleaseAss =
        "[Script Info]\nScriptType: v4.00+\nCollisions: Normal\nPlayResX: 1920\nPlayResY: 1080\nWrapStyle: 0\nScaledBorderAndShadow: yes\n\n" +
        "[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n" +
        "Style: Default,sans-serif,71,&H00FFFFFF,&H00FFFFFF,&H000F0F0F,&H000F0F0F,0,0,0,0,100,100,0,0.00,1,2.37,1.97,2,20,20,20,0\n" +
        "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n" +
        "Dialogue: 0,0:00:11.22,0:00:13.81,Default,,0,0,0,,{\\an8}NAPIS NA SZYLDZIE\n" +
        "Dialogue: 0,0:00:42.83,0:00:45.75,Default,,0,0,0,,{\\an8}Pierwsza linia.\n" +
        "Dialogue: 0,0:00:46.00,0:00:48.00,Default,,0,0,0,,Druga linia.\n";

    [TestMethod]
    public void ToAssColor_ConvertsRgbToBgrWithAlpha()
    {
        Assert.AreEqual("&H0000FFFF", AssBuilder.ToAssColor("#FFFF00", "#FFFFFF", 0));
        Assert.AreEqual("&H80000000", AssBuilder.ToAssColor("#000000", "#FFFFFF", 0x80));
        Assert.AreEqual("&H00FFFFFF", AssBuilder.ToAssColor("bogus", "#FFFFFF", 0));
    }

    [TestMethod]
    public void BuildStyleLine_DefaultStyle()
    {
        Assert.AreEqual(YellowStyle, AssBuilder.BuildStyleLine(new SubtitleStyle()));
    }

    [TestMethod]
    public void BuildStyleLine_BackgroundBox()
    {
        string box = AssBuilder.BuildStyleLine(new SubtitleStyle { Background = true, BackgroundColor = "#000000", BackgroundOpacity = 60, Outline = 2 });
        StringAssert.Contains(box, ",&H66000000,");
        StringAssert.Contains(box, ",0,0,3,6,");
    }

    [TestMethod]
    public void Patch_SetsCanvasStyleAndMarker_AndIsIdempotent()
    {
        string patched = AssBuilder.Patch(FfmpegAss, YellowStyle, "abc");
        StringAssert.Contains(patched, "PlayResX: 1920");
        StringAssert.Contains(patched, "PlayResY: 1080");
        StringAssert.Contains(patched, YellowStyle);
        StringAssert.Contains(patched, "{\\an8}Napis u góry.");
        StringAssert.Contains(patched, AssBuilder.Marker);
        Assert.AreEqual(patched, AssBuilder.Patch(patched, YellowStyle, "abc"));

        string path = Path.Combine(Path.GetTempPath(), $"posubs-{Guid.NewGuid():N}.ass");
        try
        {
            File.WriteAllText(path, patched);
            Assert.IsTrue(AssBuilder.IsOwnFile(path, out string? hash));
            Assert.AreEqual("abc", hash);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [TestMethod]
    public void Restyle_RecoloursWhiteReleaseStyle_KeepsEverythingElse()
    {
        string restyled = AssBuilder.Restyle(ReleaseAss, "#FFFF00", "h1", out int changed);
        Assert.AreEqual(1, changed);
        StringAssert.Contains(restyled, "Style: Default,sans-serif,71,&H0000FFFF,&H0000FFFF,&H000F0F0F,&H000F0F0F,0,0,0,0,100,100,0,0.00,1,2.37,1.97,2,20,20,20,0");
        Assert.AreEqual(AssBuilder.CountDialogues(ReleaseAss), AssBuilder.CountDialogues(restyled));
        StringAssert.Contains(restyled, "{\\an8}Pierwsza linia.");
        Assert.AreEqual(restyled, AssBuilder.Restyle(restyled, "#FFFF00", "h1", out int again));
        Assert.AreEqual(0, again);
    }

    [TestMethod]
    public void Restyle_KeepsColouredStylesAlphaAndInlineOverrides()
    {
        const string multi =
            "[Script Info]\nScriptType: v4.00+\n\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold\n" +
            "Style: Default,Arial,50,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0\n" +
            "Style: Sign,Arial,40,&H0000FF00,&H0000FF00,&H00000000,&H00000000,0\n" +
            "Style: Top,Arial,50,&H40F0F0F0,&H40F0F0F0,&H00000000,&H00000000,0\n\n" +
            "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n" +
            "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,{\\c&HFFFFFF&}x\n";
        string restyled = AssBuilder.Restyle(multi, "#FFFF00", "h", out int changed);
        Assert.AreEqual(2, changed);
        StringAssert.Contains(restyled, "Style: Default,Arial,50,&H0000FFFF,&H000000FF,");
        StringAssert.Contains(restyled, "Style: Sign,Arial,40,&H0000FF00,&H0000FF00,");
        StringAssert.Contains(restyled, "Style: Top,Arial,50,&H4000FFFF,&H4000FFFF,");
        StringAssert.Contains(restyled, "{\\c&HFFFFFF&}x");
    }

    [TestMethod]
    public void Restyle_HandlesDecimalSsaColours()
    {
        const string ssa =
            "[Script Info]\nScriptType: v4.00\n\n[V4 Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, TertiaryColour, BackColour\n" +
            "Style: Default,Arial,20,16777215,65535,0,0\n\n[Events]\n";
        string restyled = AssBuilder.Restyle(ssa, "#FFFF00", "h", out int changed);
        Assert.AreEqual(1, changed);
        StringAssert.Contains(restyled, "Style: Default,Arial,20,&H0000FFFF,65535,");
    }

    [TestMethod]
    public void ConvertTextAsync_PipesSrtThroughFfmpeg()
    {
        // Needs ffmpeg; set POSUBS_FFMPEG to run it (e.g. a wrapper calling the Jellyfin container's ffmpeg).
        string? ffmpeg = Environment.GetEnvironmentVariable("POSUBS_FFMPEG");
        if (string.IsNullOrEmpty(ffmpeg))
        {
            Assert.Inconclusive("POSUBS_FFMPEG not set");
        }

        const string srt = "1\n00:00:01,000 --> 00:00:02,000\n{\\an8}Dość dobre.\n\n2\n00:00:03,000 --> 00:00:04,000\nZwykły napis.\n";
        string ass = AssBuilder.Patch(AssBuilder.ConvertTextAsync(ffmpeg, srt, CancellationToken.None).GetAwaiter().GetResult(), YellowStyle, "h");
        Assert.AreEqual(2, AssBuilder.CountDialogues(ass));
        StringAssert.Contains(ass, "{\\an8}Dość dobre.");
        StringAssert.Contains(ass, YellowStyle);
    }
}
